1	// Replay runner (DESIGN.md §"Replay at the parent commit", §"Grade"): for each (task, setup), a sandbox at the
2	// task's parent commit, the setup's rules, the harness, a grade in a separate copy, failure codes, one Replay row.
3	//
4	//   const replays = await runReplays({ repo, tasks, setups, workRoot, maxCostUsd: 5 });
5	//
6	// Never throws for one run going wrong: a harness error is a Replay with verdict agent_error. Runs that are not
7	// started (unavailable candidate, budget reached, unsupported harness) are reported through `onSkip`.
8	
9	import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
10	import { homedir, tmpdir } from "node:os";
11	import { join, posix, resolve, sep } from "node:path";
12	import { runClaude } from "../harness/claude.ts";
13	import type { HarnessResult } from "../harness/types.ts";
14	import { grade, isTestFile, type GradeResult } from "../grade/index.ts";
15	import { classify, parseTranscript, type Transcript } from "../grade/taxonomy.ts";
16	import { createSandbox, destroySandbox, proveIsolation, runGit, type IsolationProof } from "../sandbox/index.ts";
17	import { identify } from "../identity/index.ts";
18	import { fetchCheckpoints } from "../ingest/fetch.ts";
19	import { parseCheckpoints } from "../ingest/parse.ts";
20	import { loadSetups, type RunnableSetup } from "../setups/registry.ts";
21	import { FailureCode, type Replay, type ReplayVerdict } from "../types.ts";
22	import type { ReplayBatch, ToolBackend } from "../agent/tools.ts";
23	import { planReplayTasks, type ReplayTask } from "./tasks.ts";
24	
25	export interface SkippedRun {
26	  task: string;
27	  setup: string;
28	  reason: string;
29	}
30	
31	export interface RunReplaysOptions {
32	  /** Local path of the repo the tasks come from. */
33	  repo: string;
34	  tasks: ReplayTask[];
35	  setups: RunnableSetup[];
36	  /** Sandboxes go here. Must not be under $HOME. */
37	  workRoot: string;
38	  /** Concurrent runs. Default 3. */
39	  parallel?: number;
40	  /** No new run starts once the summed cost of finished runs reaches this. */
41	  maxCostUsd: number;
42	  harness?: typeof runClaude;
43	  planId?: string;
44	  attempt?: number;
45	  /** Spend cap per harness run, also bounded by what is left of maxCostUsd. Default 2. */
46	  perRunUsd?: number;
47	  maxTurns?: number;
48	  timeoutMs?: number;
49	  /** Test command for grading; default: detected from the sandbox. */
50	  testCmd?: string;
51	  /** The real `claude` binary the setting-sources shim execs. Default "claude" on the child's PATH. */
52	  claudeBin?: string;
53	  keepSandboxes?: boolean;
54	  onSkip?: (s: SkippedRun) => void;
55	}
56	
57	const DEFAULT_PARALLEL = 3;
58	const DEFAULT_PER_RUN_USD = 2;
59	const DEFAULT_MAX_TURNS = 30;
60	const DEFAULT_TIMEOUT_MS = 20 * 60_000;
61	export const LOCAL_RULES_NAME = "CLAUDE.local.md";
62	export const SETTING_SOURCES = "project,local";
63	
64	/** Default work root: the OS temp dir, never $HOME. */
65	export function defaultWorkRoot(): string {
66	  return join(tmpdir(), "roster-replays");
67	}
68	
69	function underHome(path: string): boolean {
70	  const home = resolve(homedir());
71	  const p = resolve(path);
72	  return p === home || p.startsWith(home + sep);
73	}
74	
75	/**
76	 * The harness pins `--setting-sources project`; replays also load CLAUDE.local.md, which needs `local`.
77	 * This shim rewrites that one value and execs the real binary.
78	 */
79	export function writeSettingSourcesShim(dir: string, target = "claude"): string {
80	  mkdirSync(dir, { recursive: true });
81	  const path = join(dir, "claude-setting-sources");
82	  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
83	  writeFileSync(
84	    path,
85	    `#!/bin/bash
86	# Written by src/replay/run.ts: --setting-sources project -> ${SETTING_SOURCES}
87	args=(); prev=""
88	for a in "$@"; do
89	  if [ "$prev" = "--setting-sources" ] && [ "$a" = "project" ]; then a=${q(SETTING_SOURCES)}; fi
90	  args+=("$a"); prev="$a"
91	done
92	exec ${q(target)} "\${args[@]}"
93	`,
94	  );
95	  chmodSync(path, 0o755);
96	  return path;
97	}
98	
99	/** Why a setup cannot run, or null when it can. */
100	function unavailable(setup: RunnableSetup): string | null {
101	  if (setup.candidate && Object.keys(setup.env).length === 0) return "unavailable";
102	  if (setup.harness !== "claude-code") return `unsupported harness ${setup.harness}`;
103	  return null;
104	}
105	
106	/** Directories the original change touched, for the scope guard. */
107	function touchedDirs(repo: string, task: ReplayTask): string[] | undefined {
108	  try {
109	    const files = runGit(repo, ["diff", "--name-only", task.parentSha, task.originalSha]).split("\n").filter(Boolean);
110	    return [...new Set(files.map((f) => posix.dirname(f)))];
111	  } catch {
112	    return undefined;
113	  }
114	}
115	
116	/**
117	 * The harness writes `--output-format json` (one result object), not stream-json. Both parse here; a result-only
118	 * transcript has no tool calls, so it carries no evidence for F2.
119	 */
120	function loadTranscript(path: string | null): { t: Transcript; hasCalls: boolean } {
121	  let text = "";
122	  try {
123	    if (path && existsSync(path)) text = readFileSync(path, "utf8");
124	  } catch {}
125	  let t = parseTranscript(text);
126	  if (t.turns === 0 && t.result === null && text.trim()) {
127	    try {
128	      const j = JSON.parse(text);
129	      t = parseTranscript((Array.isArray(j) ? j : [j]).map((e) => JSON.stringify(e)).join("\n"));
130	    } catch {}
131	  }
132	  return { t, hasCalls: t.turns > 0 };
133	}
134	
135	function verdictOf(g: GradeResult, hasHidden: boolean): ReplayVerdict {
136	  if (hasHidden && !g.hiddenPass) return "hidden_tests_failed";
137	  if (!g.suitePass) return "suite_failed";
138	  if (!g.scopeOk) return "guardrail_flagged";
139	  return "pass";
140	}
141	
142	const ERROR_CODE: Partial<Record<string, FailureCode>> = {
143	  timeout: FailureCode.F5,
144	  max_turns: FailureCode.F5,
145	  budget: FailureCode.F5,
146	  spawn_failed: FailureCode.F6,
147	  setup_failed: FailureCode.F6,
148	};
149	
150	/** One (task, setup) run. Never throws. */
151	async function runOne(
152	  o: RunReplaysOptions & { harness: typeof runClaude; bin: string },
153	  task: ReplayTask,
154	  setup: RunnableSetup,
155	  budgetUsd: number,
156	): Promise<Replay> {
157	  const attempt = o.attempt ?? 1;
158	  const planId = o.planId ?? "adhoc";
159	  const row: Replay = {
160	    id: `${planId}:${task.id}:${setup.id}:${attempt}`,
161	    plan_id: planId,
162	    task_session_id: task.id,
163	    setup_id: setup.id,
164	    attempt,
165	    isolation_proof: "",
166	    turns: null,
167	    duration_ms: null,
168	    cost_usd: null,
169	    hidden_pass: null,
170	    suite_pass: null,
171	    scope_ok: null,
172	    judge_equiv: null,
173	    failure_codes: [],
174	    verdict: "agent_error",
175	    transcript_ref: null,
176	    trace_url: null,
177	  };
178	  const fail = (code: FailureCode, why: string): Replay => {
179	    row.failure_codes = [code];
180	    if (!row.isolation_proof) row.isolation_proof = JSON.stringify({ ok: false, checks: [], error: why });
181	    return row;
182	  };
183	
184	  let sandboxPath: string | null = null;
185	  try {
186	    const sb = await createSandbox(o.repo, task.parentSha, { root: o.workRoot });
187	    sandboxPath = sb.path;
188	    const proof: IsolationProof = await proveIsolation(sb.path, o.repo, task.parentSha);
189	    row.isolation_proof = JSON.stringify(proof);
190	    if (!proof.ok) return fail(FailureCode.F6, "isolation proof failed");
191	
192	    // Rules in, committed as `setup:` so neither the agent's diff nor the grade sees them.
193	    writeFileSync(join(sb.path, "CLAUDE.md"), readFileSync(setup.rulesPath, "utf8"));
194	    const ruleFiles = ["CLAUDE.md"];
195	    if (setup.extraRulesPath) {
196	      writeFileSync(join(sb.path, LOCAL_RULES_NAME), readFileSync(setup.extraRulesPath, "utf8"));
197	      ruleFiles.push(LOCAL_RULES_NAME);
198	    }
199	    runGit(sb.path, ["add", "-f", "--", ...ruleFiles]);
200	    runGit(sb.path, ["-c", "commit.gpgsign=false", "commit", "-q", "-m", `setup: ${ruleFiles.join(" + ")} for ${setup.id}`]);
201	    const rulesSha = runGit(sb.path, ["rev-parse", "HEAD"]);
202	
203	    let res: HarnessResult | null = null;
204	    let harnessError: string | null = null;
205	    try {
206	      res = await o.harness({
207	        sandboxPath: sb.path,
208	        prompt: task.prompt,
209	        model: setup.model,
210	        rulesFile: setup.rulesPath,
211	        maxTurns: o.maxTurns ?? DEFAULT_MAX_TURNS,
212	        timeoutMs: o.timeoutMs ?? DEFAULT_TIMEOUT_MS,
213	        budgetUsd,
214	        env: setup.env,
215	        bin: o.bin,
216	      });
217	    } catch (e) {
218	      harnessError = e instanceof Error ? e.message : String(e);
219	    }
220	    if (!res) return fail(FailureCode.F6, `harness threw: ${harnessError}`);
221	
222	    row.turns = res.turns;
223	    row.duration_ms = res.durationMs;
224	    row.cost_usd = res.costUsd;
225	    row.transcript_ref = res.transcriptPath;
226	    const { t, hasCalls } = loadTranscript(res.transcriptPath);
227	
228	    if (res.isError) {
229	      const codes = new Set(classify({ verdict: "agent_error" }, null, t).map((c) => c.code));
230	      const forced = res.errorKind ? ERROR_CODE[res.errorKind] : undefined;
231	      if (forced === FailureCode.F6) codes.clear();
232	      if (forced) codes.add(forced);
233	      if (!hasCalls) codes.delete(FailureCode.F2);
234	      // A result-only transcript of an errored run is not a kill: drop the "no result event" F5 unless forced.
235	      if (t.result === null && forced !== FailureCode.F5 && !hasCalls) codes.delete(FailureCode.F5);
236	      row.failure_codes = Object.values(FailureCode).filter((c) => codes.has(c));
237	      return row;
238	    }
239	
240	    // The agent's base is the setup commit (the harness's own when it made one).
241	    const base = res.setupSha ?? rulesSha;
242	    runGit(sb.path, ["add", "-A"]);
243	    const changed = runGit(sb.path, ["diff", "--cached", "--name-only", base]).split("\n").filter(Boolean);
244	    let g: GradeResult | null = null;
245	    if (changed.length === 0) row.verdict = "no_changes";
246	    else {
247	      const preexistingTests = runGit(sb.path, ["ls-tree", "-r", "--name-only", base]).split("\n").filter(isTestFile);
248	      g = await grade({
249	        sandbox: { path: sb.path, baseSha: base },
250	        hidden: task.hiddenTests,
251	        testCmd: o.testCmd,
252	        preexistingTests,
253	        touchedDirs: touchedDirs(o.repo, task),
254	      });
255	      const hasHidden = task.hiddenTests.length > 0;
256	      row.hidden_pass = hasHidden ? g.hiddenPass : null;
257	      row.suite_pass = g.suitePass;
258	      row.scope_ok = g.scopeOk;
259	      row.verdict = verdictOf(g, hasHidden);
260	    }
261	    // The run finished without error, so a missing result event is not a kill.
262	    const result = t.result ?? { subtype: "success", isError: false, numTurns: res.turns, terminalReason: res.stopReason };
263	    const codes = classify({ verdict: row.verdict }, g, { ...t, result }).map((c) => c.code);
264	    row.failure_codes = hasCalls ? codes : codes.filter((c) => c !== FailureCode.F2);
265	    return row;
266	  } catch (e) {
267	    // Sandbox, rules or grading broke: the environment, not the agent.
268	    row.verdict = "agent_error";
269	    row.hidden_pass = row.suite_pass = row.scope_ok = null;
270	    return fail(FailureCode.F6, e instanceof Error ? e.message : String(e));
271	  } finally {
272	    if (sandboxPath && !o.keepSandboxes) await destroySandbox(sandboxPath);
273	  }
274	}
275	
276	export interface ReplayRunnerDeps {
277	  /** The repo under review (git URL or local path), as given to `roster run`. */
278	  repo?: string;
279	  cacheDir: string;
280	  /** Where setups/ lives. Default: the working directory. */
281	  setupsRoot?: string;
282	  env?: Record<string, string | undefined>;
283	  workRoot?: string;
284	  parallel?: number;
285	  harness?: typeof runClaude;
286	  testCmd?: string;
287	}
288	
289	/** The coordinator's `runReplays` dependency: resolves task and setup ids, then runs them. */
290	export function replayRunner(deps: ReplayRunnerDeps): ToolBackend["runReplays"] {
291	  return async ({ plan_id, tasks: taskIds, setups: setupIds, max_cost_usd }) => {
292	    if (!deps.repo) throw new Error("no repo configured for replays");
293	    const f = await fetchCheckpoints(deps.repo, { cacheDir: deps.cacheDir });
294	    if (f.backend === "none") throw new Error("no Entire checkpoints found in this repo");
295	    const sessions = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch").map((s) => ({
296	      ...s,
297	      setup_id: identify(s, f.repoPath).setupId,
298	    }));
299	    const planned = new Map(planReplayTasks(f.repoPath, sessions, []).tasks.map((t) => [t.id, t]));
300	    const missingTasks = taskIds.filter((t) => !planned.has(t));
301	    if (missingTasks.length) throw new Error(`no replayable task for session(s) ${missingTasks.join(", ")}`);
302	    const known = new Map(loadSetups(deps.setupsRoot ?? process.cwd(), deps.env ?? process.env).map((s) => [s.id, s]));
303	    const missingSetups = setupIds.filter((s) => !known.has(s));
304	    if (missingSetups.length) throw new Error(`unknown setup(s) ${missingSetups.join(", ")}`);
305	
306	    const skipped: SkippedRun[] = [];
307	    const replays = await runReplays({
308	      repo: f.repoPath,
309	      tasks: taskIds.map((t) => planned.get(t)!),
310	      setups: setupIds.map((s) => known.get(s)!),
311	      workRoot: deps.workRoot ?? defaultWorkRoot(),
312	      parallel: deps.parallel,
313	      maxCostUsd: max_cost_usd,
314	      harness: deps.harness,
315	      testCmd: deps.testCmd,
316	      planId: plan_id,
317	      onSkip: (s) => skipped.push(s),
318	    });
319	    const cost_usd = replays.reduce((s, r) => s + (r.cost_usd ?? 0), 0);
320	    return { replays, cost_usd, skipped } as ReplayBatch;
321	  };
322	}
323	
324	export async function runReplays(opts: RunReplaysOptions): Promise<Replay[]> {
325	  const workRoot = resolve(opts.workRoot);
326	  if (underHome(workRoot)) throw new Error(`workRoot ${workRoot} is under $HOME; replays must run outside it`);
327	  mkdirSync(workRoot, { recursive: true });
328	  const bin = writeSettingSourcesShim(join(workRoot, "bin"), opts.claudeBin);
329	  const o = { ...opts, workRoot, harness: opts.harness ?? runClaude, bin };
330	  const skip = (task: string, setup: string, reason: string) => opts.onSkip?.({ task, setup, reason });
331	
332	  const queue: Array<{ task: ReplayTask; setup: RunnableSetup; order: number }> = [];
333	  for (const task of opts.tasks) {
334	    for (const setup of opts.setups) {
335	      const why = unavailable(setup);
336	      if (why) skip(task.id, setup.id, why);
337	      else queue.push({ task, setup, order: queue.length });
338	    }
339	  }
340	
341	  const out: Array<{ order: number; replay: Replay }> = [];
342	  let spent = 0;
343	  let next = 0;
344	  const worker = async () => {
345	    while (next < queue.length) {
346	      const job = queue[next++]!;
347	      const left = opts.maxCostUsd - spent;
348	      if (left <= 0) {
349	        skip(job.task.id, job.setup.id, `budget: spent $${spent.toFixed(4)} of $${opts.maxCostUsd}`);
350	        continue;
351	      }
352	      const replay = await runOne(o, job.task, job.setup, Math.min(opts.perRunUsd ?? DEFAULT_PER_RUN_USD, left));
353	      spent += replay.cost_usd ?? 0;
354	      out.push({ order: job.order, replay });
355	    }
356	  };
357	  const n = Math.max(1, Math.floor(opts.parallel ?? DEFAULT_PARALLEL));
358	  await Promise.all(Array.from({ length: Math.min(n, queue.length) }, worker));
359	  return out.sort((a, b) => a.order - b.order).map((x) => x.replay);
360	}
